export const CSS: Record<string, string> = {
  "arxiv/style": "/*\n * arXiv preprint: the PRIMEarxiv class (the PRIME AI paper template), drawn in CSS.\n *\n * Class   PRIMEarxiv.sty, after George Kour's arxiv-style (MIT, Copyright (c) 2020 George Kour; adapted by Moulay Akhloufi). See SOURCE.txt.\n * CSS     Writ. Written in bare RASH selectors, like rash.css; index.ts binds them to the paper box (scope.ts), and :scope is that box.\n *         Calibrated against the class's own PDF: `make eval ARGS=arxiv` in the compiler repo.\n *\n * Measures (pt unless noted)\n *   Page         US Letter, 215.9 x 279.4 mm; text 6.5in wide\n *   Margins      top 73.5, left and right 72, bottom 69; on page 1 the top is 72, with no head or number\n *   Head, number head 26.5 above the text area (italic 10, right); number 18 below (10, centred)\n *   Body         Times 10 on 10.91 (line-height 1.091), justified; 5.5 between paragraphs; extra space after a sentence's full stop\n *   Title        17.28 (\\LARGE), small caps (.8), between two 2pt rules; 7.2 above, 36.25 below\n *   Authors      bold names, affiliations at body size, e-mails Courier 8; columns share the free width; 40.5 below\n *   Abstract     0.5in in from each side; heading 12, small caps (.8), centred; 10.6 below\n *   Headings     12 / 10 / 10 bold; space above 16 / 13.4 / 12.5, below 11.5 / 9.5 / 7.75; \\paragraph runs into its text\n *   Lists        35.5 in; quotes 35.5 in; \\verb blocks 17 in; items 3.5 apart; display blocks 10.25 above and below\n *   References   [n] label, 16.5 hanging indent, 4 between entries\n *   Footnotes    9 on 9, 12.65 in; separator rule 2in x 0.5; call mark at 0.7 of the size, raised\n *   Tables       booktabs rules .8 outer, .5 under the header, .4 under a spanning header; 6 cell padding at the sides\n *   Figures      caption 7 away, 9.5 below (tables 22)\n */\n\n/* The PRIMEarxiv class: a fixed right head and a centred page number. TeX puts the first baseline \\topskip (10pt) below the text area and ends the area on a baseline, so after page 1 the area starts 3.5pt lower and ends 3pt lower. Head: 26.5pt above the area; number: 20pt below it. */\n@page {\n  size: letter;\n  margin: 73.5pt 72pt 69pt;\n  @top-right {\n    content: \"PRIME AI paper\";\n    font: italic 10pt \"Times New Roman\", \"Nimbus Roman\", Times, serif;\n    vertical-align: bottom;\n    padding-bottom: 26.5pt;\n  }\n  @bottom-center {\n    content: counter(page);\n    font: 10pt \"Times New Roman\", \"Nimbus Roman\", Times, serif;\n    vertical-align: top;\n    padding-top: 18pt;\n  }\n}\n\n@page :first {\n  margin-top: 72pt;\n  @top-left {\n    content: none;\n  }\n  @top-right {\n    content: none;\n  }\n  @bottom-center {\n    content: none;\n  }\n}\n\n:scope {\n  font: 10pt/1.091 \"Times New Roman\", \"Nimbus Roman\", Times, var(--font-serif4, serif), serif;\n}\n\n/* \\LARGE (17.28pt) between two 2pt rules at the class's positions: the top rule's top edge 7.2pt below the text area, 49.3pt to the bottom rule's lower edge. The rules are background strips: a 2pt border is snapped to 1.5pt when printed. */\n.p-title {\n  font-size: 17.28pt;\n  font-weight: 400;\n  text-align: center;\n  border: 0;\n  background: linear-gradient(#000, #000) top left / 100% 2pt no-repeat, linear-gradient(#000, #000) bottom left / 100% 2pt no-repeat;\n  padding: 20.8pt 0 10.25pt;\n  margin: 7.2pt 0 36.25pt;\n  letter-spacing: .04em;\n}\n\n/* \\sc: the lowercase letters are capitals at 0.8 of the size, as the class's small-caps font has them (CSS small-caps would synthesize 0.7) */\n.p-sc {\n  text-transform: uppercase;\n  font-size: .8em;\n}\n\n/* The subtitle is the line under the title (\"A Preprint\" in the template), and the running head on the right. */\n.p-subtitle {\n  font: 400 10pt var(--serif);\n  font-variant: small-caps;\n  letter-spacing: .05em;\n  text-align: center;\n  opacity: 1;\n  margin: 0 0 14pt;\n  string-set: subtitle content(text);\n}\n\n/* The byline is RASH's own markup (one <address class=\"authors\"> per group of authors): \\And is \\hfil\\hfil inside \\centering, so the leftover width is shared equally before, between and after the columns. */\n.p-authors {\n  font-weight: 700;\n  text-align: center;\n  margin: 0 0 40.5pt;\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: space-evenly;\n  column-gap: 1em;\n}\n\n.p-authors address {\n  font-style: normal;\n  font-weight: 400;\n}\n\n.p-authors .author_name {\n  font-weight: 700;\n}\n\n.p-authors .affiliation,\n.p-authors .email {\n  display: block;\n}\n\n/* arXiv sets affiliations at body size; the email line is monospace (\\texttt) */\n.p-authors .email {\n  position: relative;\n  top: -3pt; /* the class sets this line closer to the affiliations than its own line height */\n  font-family: \"Courier New\", Courier, monospace;\n  font-size: .8em;\n}\n\n.p-date {\n  flex-basis: 100%;\n  font-weight: 400;\n  margin-top: 20pt;\n}\n\n.orcid {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 2em;\n  height: 2em;\n  margin-right: .5em;\n  border-radius: 50%;\n  background: #a6ce39;\n  color: #fff;\n  font: 700 .55em/1 Helvetica, Arial, sans-serif;\n  letter-spacing: 0;\n  vertical-align: .15em;\n}\n\n.p-aff .orcid {\n  display: none;\n}\n\n.p-keywords::before {\n  content: \"Keywords \";\n  font-style: italic;\n  margin-right: .4em;\n}\n\np {\n  margin: 0 0 5.5pt;\n  text-align: justify;\n}\n\n/* Heading spacing measured against the class (its skips plus the 5.5pt \\parskip TeX adds around a heading): above / below */\nsection > h1 {\n  font-size: 12pt;\n  font-weight: 700;\n  margin: 16pt 0 11.5pt;\n}\n\nsection section > h1 {\n  font-size: 10pt;\n  margin: 13.4pt 0 9.5pt;\n}\n\nsection section section > h1 {\n  margin: 12.5pt 0 7.75pt;\n}\n\n/* \\paragraph: the bold label runs on at the start of the paragraph's first line, 1em before the text */\nsection section section section > h1 {\n  display: inline;\n  margin: 0 1em 0 0;\n}\n\nsection section section section > h1 + p {\n  display: inline;\n}\n\nsection section section section {\n  margin-top: 12.75pt;\n}\n\nsection section section section::after {\n  content: \"\";\n  display: block;\n  margin-bottom: 4.5pt;\n}\n\n:scope > section:not([role]) > h1::before {\n  content: counter(h1) \"\\2003\";\n}\n\n:scope > section:not([role]) > section:not([role]) > h1::before {\n  content: counter(h1) \".\" counter(h2) \"\\2003\";\n}\n\n:scope > section:not([role]) > section:not([role]) > section:not([role]) > h1::before {\n  content: counter(h1) \".\" counter(h2) \".\" counter(h3) \"\\2003\";\n}\n\nsection[role=\"doc-abstract\"] {\n  margin: 0 0.5in 9.5pt;\n}\n\nsection[role=\"doc-abstract\"] > h1 {\n  font-size: 12pt;\n  text-align: center;\n  margin: 0 0 6pt;\n}\n\nsection[role=\"doc-bibliography\"] > ul {\n  list-style: none;\n  padding: 0;\n  counter-reset: ref;\n}\n\nsection[role=\"doc-bibliography\"] li {\n  counter-increment: ref;\n  padding-left: 16.5pt;\n  text-indent: -16.5pt;\n  margin-bottom: 4pt;\n}\n\nsection[role=\"doc-bibliography\"] li::before {\n  content: \"[\" counter(ref) \"]\";\n  display: inline-block;\n  width: 16.5pt;\n  text-indent: 0;\n}\n\nfigcaption::before {\n  font-weight: 400;\n}\n\n.p-foot {\n  float: footnote;\n  font: 400 9pt/1 var(--serif);\n  text-align: left;\n}\n\n.p-foot::footnote-call {\n  content: \"*\";\n  vertical-align: super;\n  font-size: .7em;\n  line-height: 0;\n}\n\n/* the footnote is moved out of the paper box into the page's footnote area, so these cannot be scoped to it.\n   Its mark is a raised numeral (\\textsuperscript), not the list marker \"2.\" Paged.js would print at body size. */\n.pagedjs_footnote_content .p-foot[data-footnote-marker],\n.pagedjs_footnote_content .p-note[data-footnote-marker] {\n  list-style: none;\n}\n.pagedjs_footnote_content .p-foot[data-footnote-marker]::before {\n  content: \"*\";\n  vertical-align: super;\n  font-size: .7em;\n  line-height: 0;\n}\n.pagedjs_footnote_content .p-note[data-footnote-marker]::before {\n  content: counter(footnote-marker);\n  vertical-align: super;\n  font-size: .7em;\n  line-height: 0;\n}\n\n.pagedjs_footnote_content .p-foot {\n  font: 400 9pt/1 \"Times New Roman\", \"Nimbus Roman\", Times, serif;\n  text-align: left;\n  padding-left: 12.65pt; /* the class indents a note 12.65 before its mark */\n}\n\n@page {\n  @footnote {\n    background: linear-gradient(#000, #000) top left / 2in .5pt no-repeat;\n    padding-top: 1pt;\n    margin-top: 0;\n  }\n}\n\n/* calibrated: the class text area ends ~6.5pt lower on a page with a footnote */\n\n/* footnotes: numbered, at the foot of the page (the title's note keeps the star, .p-foot above) */\n.p-note {\n  float: footnote;\n  font: 400 9pt/1 \"Times New Roman\", \"Nimbus Roman\", Times, serif;\n  text-align: left;\n}\n\n.p-note::footnote-call {\n  vertical-align: super;\n  font-size: .7em;\n  line-height: 0;\n}\n\n.pagedjs_footnote_content .p-note {\n  font: 400 9pt/1 \"Times New Roman\", \"Nimbus Roman\", Times, serif;\n  text-align: left;\n  padding-left: 12.65pt; /* the class indents a note 12.65 before its mark */\n}\n\n/* links get a box, as hyperref draws them: red internal references, green citations, cyan addresses */\n.p-ref {\n  outline: .5pt solid #f00;\n  outline-offset: 1pt;\n}\n\n.p-cite {\n  outline: .5pt solid #0f0;\n  outline-offset: 1pt;\n}\n\n.p-url {\n  outline: .5pt solid #0ff;\n  outline-offset: 1pt;\n}\n\n/* a display formula with an id is numbered, the number at the right margin */\n.display_formula {\n  position: relative;\n  text-align: center;\n  margin: -3.3pt 0 14.5pt;\n}\n\n.display_formula[id] {\n  counter-increment: eq;\n}\n\n.display_formula[id]::after {\n  content: \"(\" counter(eq) \")\";\n  position: absolute;\n  right: 0;\n  top: 50%;\n  transform: translateY(-50%);\n}\n\n.katex {\n  font-size: 1em;\n}\n\n/* the entry's paragraph runs on after the [n] label, so the hanging indent works */\nsection[role=\"doc-bibliography\"] li > p {\n  display: inline;\n  margin: 0;\n}\n\n/* \\texttt in the class: Courier at 8.75pt has the 5.25pt advance of Computer Modern Typewriter at 10pt */\ncode,\npre,\n.p-url {\n  font-family: \"Courier New\", Courier, \"Liberation Mono\", monospace;\n  font-size: 8.75pt;\n}\n\npre {\n  line-height: 1.2;\n}\n\n/* the footnote mark in the text is a link too, boxed red like the other internal references (the title's star is not) */\na[data-footnote-call].p-note {\n  outline: .5pt solid #f00;\n  outline-offset: 1pt;\n}\n\n/* captions as the class prints them: \"Figure 1: text\" below a figure, \"Table 1: text\" above a table (7pt away) */\nfigcaption::before {\n  content: \"Figure \" counter(figure) \": \";\n  font-weight: 400;\n}\n\nfigure:has(> table) figcaption::before {\n  content: \"Table \" counter(table) \": \";\n}\n\nfigure:has(> pre) figcaption::before {\n  content: \"Listing \" counter(listing) \": \";\n}\n\nfigcaption {\n  margin-top: 7pt;\n}\n\nfigure:has(> table) {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n}\n\nfigure:has(> table) figcaption {\n  order: -1;\n  margin: 0 0 7pt;\n}\n\n/* booktabs: heavy top and bottom rule, a light rule under the header, plain header cells, a spanning header centred over its columns */\nfigure table {\n  border-top: .8pt solid #000;\n  border-bottom: .8pt solid #000;\n}\n\nth {\n  font-weight: 400;\n}\n\nth[colspan] {\n  text-align: center;\n  border-bottom: .4pt solid #000;\n}\n\ntr:has(> th):has(+ tr > td) > th {\n  border-bottom: .5pt solid #000;\n}\n\n/* line breaking closer to TeX */\n:scope {\n  hyphens: auto;\n}\n\n/* TeX shrinks interword glue up to ~1/3 to fit more on a line; a browser only stretches. A narrower base space, re-stretched by justification, packs the same. */\np,\nli {\n  word-spacing: -.06em;\n}\n\n/* the title's star: a thin space after the title and raised like \\thanks */\n.p-title a[data-footnote-call] {\n  margin-left: 3pt;\n  position: relative;\n  top: -2pt;\n}\n\n/* display blocks as the class sets them: 9.5pt between lines, \\verb-style block indented 17pt, quote 35.5pt, lists 35.5pt, \\parskip 3.5pt between items */\npre,\nblockquote,\np[style*=\"text-align:center\"] {\n  margin: 10.25pt 0;\n}\np[style*=\"text-align:center\"]:has(+ section) {\n  margin-bottom: 15.5pt; /* a display block before a heading: the class leaves 2pt more than the heading's own space */\n}\n\npre {\n  margin-left: 17pt;\n}\n\nblockquote {\n  margin-left: 35.5pt;\n  margin-right: 0;\n}\n\nul,\nol {\n  padding-left: 35.5pt;\n}\n\nli > p {\n  margin-bottom: 3.5pt;\n}\n\ntd {\n  padding: 0 6pt;\n  line-height: 1.1;\n}\n\ntr:has(> th) + tr > td {\n  padding-top: 3pt;\n}\n\ntr:last-child > td {\n  padding-bottom: 2pt;\n}\n\nsection > h1 + ul {\n  margin-top: 0;\n  margin-bottom: 3pt;\n}\n\nsection section > h1:has(+ ul),\nsection section section > h1:has(+ ul) {\n  margin-bottom: 5pt;\n}\n\n/* beats the heading rules above */\ntd .katex {\n  line-height: 1.1;\n}\n\n/* KaTeX's 1.2 would grow the row */\nfigure {\n  margin: 0 0 9.5pt;\n}\n\nfigure:has(> table) {\n  margin-bottom: 22pt;\n}\n/* the extra space TeX puts after a sentence-ending full stop: the base word-spacing above is narrower than a natural space, this one is not */\n.p-ss {\n  word-spacing: 0;\n}\n/* \\topskip: TeX puts the first baseline of a page 10pt below the top of the text area, so a page that starts with text starts about 2pt lower than one that starts with a float */\np[data-split-from] {\n  padding-top: 2.4pt !important; /* Paged.js resets the padding of a split fragment */\n}\n",
  "base": "/* Shared by every style: numbering counters (skipping abstract and bibliography), lists, code, figures, tables. */\n.paper-pdf { --sans: \"Source Sans Pro\", \"Source Sans 3\", Helvetica, Arial, sans-serif; --serif-cr: \"Crimson Text\", Crimson, Georgia, serif; --serif: \"Latin Modern Roman\", \"CMU Serif\", \"Times New Roman\", Times, var(--font-serif4), serif; }\n.paper-pdf ins.rv-ins { background: #dcfce7; color: #166534; text-decoration: none; }\n.paper-pdf del.rv-del { background: #fde2e2; color: #b42318; text-decoration: line-through; }\n.paper-pdf { counter-reset: h1 figure table listing eq; color: #000; }\n.paper-pdf section > h1 { break-after: avoid; }\n:is(.paper-pdf, .p-first, .p-rest) > section:not([role]) { counter-increment: h1; counter-reset: h2; }\n:is(.paper-pdf, .p-first, .p-rest) > section:not([role]) > section:not([role]) { counter-increment: h2; counter-reset: h3; }\n:is(.paper-pdf, .p-first, .p-rest) > section:not([role]) > section:not([role]) > section:not([role]) { counter-increment: h3; }\n.paper-pdf p { margin: 0; orphans: 2; widows: 2; text-align: justify; }\n.paper-pdf ul, .paper-pdf ol { margin: 4pt 0; padding-left: 1.6em; }\n.paper-pdf ul { list-style: disc; } .paper-pdf ol { list-style: decimal; }\n.paper-pdf pre { font: 8pt/1.4 var(--font-jetbrains, monospace), monospace; text-align: left; white-space: pre-wrap; break-inside: avoid; }\n.paper-pdf code { font-family: var(--font-jetbrains, monospace), monospace; font-size: .9em; }\n.paper-pdf a { color: inherit; text-decoration: none; }\n.paper-pdf a[href^=\"#fn-\"] { font-size: .75em; vertical-align: super; line-height: 0; }\n.paper-pdf span[role=\"math\"] { font-style: italic; }\n/* Left out of the heading counters (the editor sets data-un on them). */\n:is(.paper-pdf, .p-first, .p-rest) > section[data-un] { counter-increment: unnumbered; } /* not \"none\": paged.js reads it as a counter name and loses the heading counters after a page break */\n/* Formatting strikethrough (<s>): a plain mark like bold, not an edit. */\n.paper-pdf s { text-decoration: line-through; }\n.paper-pdf figure { margin: 1.5em 0; text-align: center; break-inside: avoid; counter-increment: figure; }\n.paper-pdf figure > p { text-align: center; }\n.paper-pdf figure img { max-width: 90%; max-height: 120mm; height: auto; display: block; margin-inline: auto; } /* block + auto margins: centered whatever the reset says */\n.paper-pdf figure:has(> p > img[style*=\"width\"]) { width: 100%; } /* a resized image is a share of the text width, so its figure must span it */\n.paper-pdf figure img[style*=\"width\"] { max-width: 100%; }\n.paper-pdf figcaption { margin-top: 5px; text-align: center; }\n.paper-pdf figcaption::before { content: \"Figure \" counter(figure) \". \"; font-weight: 700; }\n.paper-pdf figure:has(> table) { counter-increment: table; }\n.paper-pdf figure:has(> table) figcaption::before { content: \"Table \" counter(table) \". \"; }\n.paper-pdf figure:has(> pre) { counter-increment: listing; text-align: left; }\n.paper-pdf figure:has(> pre) figcaption::before { content: \"Listing \" counter(listing) \". \"; }\n.paper-pdf figure table { border-collapse: collapse; margin: 0 auto; border-top: 1px solid #000; border-bottom: 1px solid #000; }\n.paper-pdf th, .paper-pdf td { padding: 2pt 6pt; text-align: left; }\n.paper-pdf th { border-bottom: .5px solid #000; }\n.paper-pdf .p-title { string-set: title content(text); }\n.paper-pdf .p-authors { string-set: authors content(text); }\n/* Affiliation numbers and lines are generated content, so the running header (the text of .p-authors) stays names only. */\n.paper-pdf .p-author[data-refs]::after, .paper-pdf .p-aff::before { content: attr(data-refs); vertical-align: super; font-size: .7em; }\n.paper-pdf .p-aff { display: block; font-size: .8em; font-weight: 400; text-transform: none; letter-spacing: 0; }\n.paper-pdf .p-aff:first-of-type { margin-top: 4pt; }\n.paper-pdf .p-aff::after { content: \" \" attr(data-text); }\n.paper-pdf .p-subtitle { text-align: center; font-size: 1.15em; margin: -4pt 0 12pt; }\n.paper-pdf .p-keywords { margin: 0 0 12pt; text-align: left; }\n.paper-pdf .p-keywords::before { content: \"Keywords: \"; font-weight: 700; }\n/* An empty trailing page, added by the preview so a short paper always shows page 2. (Paged.js reads stylesheets, not style attributes.) */\n.p-blank { break-before: page; }\n",
  "cambridge/editor": "/* Editor glue only: the look is style.css. Selectors name .paper-pdf, .p-* and .paper-side, nothing of the editor's internals. */\n.paper { padding-left: 55mm; } /* the strip page 1's sidebar sits in */\n.paper-side { position: absolute; left: 15mm; top: 17mm; }\n.paper-side .p-side { float: none; margin: 0; }\n/* The keywords field is part of the page's text but belongs in the sidebar: it hangs in the strip under the sidebar's text (--side-h is measured in the editor). */\n.paper-pdf .p-keywords { display: block; position: absolute; left: 15mm; top: calc(17mm + var(--side-h, 70mm) + 12pt); width: 50mm; margin: 0; font: 7.5pt/9.5pt var(--sans); text-align: left; text-indent: 0; }\n/* The dropdowns look like the text they replace until you point at them. */\n.paper-side select { font: inherit; color: inherit; background: transparent; border: 1px solid transparent; border-radius: 3px; padding: 0; max-width: 100%; cursor: pointer; text-overflow: ellipsis; }\n.paper-side select:hover, .paper-side select:focus { border-color: #999; }\n",
  "cambridge/style": "/* Cambridge Large1 (class cup-journal): 210x280mm. Page 1 has a sidebar (journal, URL, article type, keywords, correspondence, publisher) beside one\n   main column; the pages after it are two columns, full width. Headings are unnumbered bold sans; the abstract is a grey box. */\n@page { size: 210mm 280mm; margin: 17mm 16mm 20mm 15mm; @top-left { content: counter(page); font: 7.5pt var(--sans); } @top-right { content: string(short); font: 600 7.5pt var(--sans); } }\n@page cover { @top-left { content: none; } @top-right { content: none; } }\n.paper-pdf .p-authors { string-set: short attr(data-short); }\n/* \"cover\" is page 1: the front matter plus the first N sections (the paper's firstPageSections field, set in the adapter); the rest starts a new page in two columns.\n   The strip is a margin, not @page, so it cannot be clipped. */\n.paper-pdf .p-first { page: cover; margin-left: 55mm; }\n.paper-pdf .p-rest { page: body; break-before: page; column-count: 2; column-gap: 5mm; }\n.paper-pdf { font: 9.5pt/12pt \"Crimson Text\", Crimson, Georgia, var(--font-serif4), serif; }\n.paper-pdf .p-side { float: left; width: 50mm; margin-left: -55mm; font: 7.5pt/9.5pt var(--sans); }\n.paper-pdf .p-side > * { margin: 0 0 9pt; }\n.paper-pdf .p-side p { text-align: left; text-indent: 0; }\n.paper-pdf .p-side .j { font: italic 9pt/11pt var(--sans); } .paper-pdf .p-side .u { font: 700 9pt/11pt var(--sans); }\n.paper-pdf .p-side .t { font: 700 12pt/14pt var(--sans); margin-top: 30pt; }\n.paper-pdf .p-side b { font-weight: 700; }\n/* Text where the class prints the publisher's logo. */\n.paper-pdf .p-side .pub { margin-top: 160mm; font: 600 17pt/17pt \"Crimson Text\", Crimson, Georgia, serif; letter-spacing: .02em; text-transform: uppercase; }\n.paper-pdf .p-side .pub small { display: block; font-size: 10pt; letter-spacing: .06em; }\n.paper-pdf .p-subtitle, .paper-pdf .p-authors, .paper-pdf .p-keywords { text-indent: 0; }\n.paper-pdf .p-title { font: 400 16pt/20pt var(--sans); margin: 0 0 12pt; }\n.paper-pdf .p-authors { font: 9pt/12pt var(--sans); border-top: .5pt solid #000; padding: 2pt 0 0; margin: 0 0 6pt; }\n/* The second rule sits between the names and the affiliations: it is the top of the first affiliation line. */\n.paper-pdf .p-aff:not(.p-aff + .p-aff) { border-top: .5pt solid #000; margin-top: 2pt; padding-top: 3pt; }\n.paper-pdf .p-aff { font-size: 6.5pt; line-height: 8pt; }\n.paper-pdf .p-aff[data-note] { display: none; } /* correspondence and emails are in the sidebar */\n.paper-pdf .p-subtitle { display: none; }\n.paper-pdf .p-keywords { display: none; }\n.paper-pdf p { text-align: justify; hyphens: auto; } .paper-pdf p + p { text-indent: 12pt; }\n.paper-pdf section > h1 { font: 700 8.5pt/10pt var(--sans); margin: 14pt 0 3pt; }\n.paper-pdf section section > h1 { font-style: italic; font-weight: 600; margin: 10pt 0 2pt; }\n.paper-pdf .p-rest > section:first-child > h1 { margin-top: 0; }\n.paper-pdf section[role=\"doc-abstract\"] { background: #d9d9d9; border-radius: 0; padding: 7pt 9pt 8pt; margin: 8pt 0 6pt; font-size: 8.5pt; line-height: 10pt; }\n.paper-pdf section[role=\"doc-abstract\"] > h1 { font-size: 8pt; margin: 0 0 3pt; }\n.paper-pdf section[role=\"doc-bibliography\"] > ul { list-style: none; padding: 0; }\n.paper-pdf section[role=\"doc-bibliography\"] li { font-size: 8pt; line-height: 10pt; padding-left: 1.5em; text-indent: -1.5em; margin-bottom: 2pt; }\n.paper-pdf figcaption { font: 8pt/10pt var(--sans); text-align: center; } .paper-pdf figcaption::before { font-weight: 700; }\n\n/* Statement sections are run-in: the heading is a bold lead-in on the first line of the text (the editor sets data-run on them). */\n.paper-pdf section[data-run] > h1 { display: inline; font: 700 9.5pt/12pt \"Crimson Text\", Crimson, Georgia, serif; margin: 0 .4em 0 0; }\n.paper-pdf section[data-run] > h1 + p { display: inline; }\n.paper-pdf section[data-run] > h1::after { content: \".\"; }\n",
  "ceur/style": "/*\n * CEUR-WS: the ceurart class (CEUR Workshop Proceedings), drawn in CSS.\n *\n * Class   ceurart.cls v0.6.2 by Dmitry S. Kulyabov (LPPL 1.3c), from the CEUR-WS template; see SOURCE.txt.\n * CSS     Writ. Bare RASH selectors, like rash.css; index.ts binds them to the paper box (scope.ts), and :scope is that box.\n *         Calibrated against the template's own PDF: `make eval ARGS=ceur` in the compiler repo.\n *\n * Measures (pt unless noted), from the class and its sample\n *   Page         A4; text 451.3 wide (side margins 72)\n *   Body         Libertinus Serif 10.95 (LaTeX's \"11pt\") on 13.5, justified\n *   Title        Libertinus Sans Bold 17.28 (\\LARGE) on 21.6, left\n *   Headings     Libertinus Sans Bold: section 12 on 14, subsection 11 on 13, subsubsection 10.5 on 12 (italic); numbered \"1.\" with a 0.5em space\n *   Abstract     indented 45 from the left; heading and \"Keywords\" in Libertinus Sans Bold\n */\n@page {\n  size: 595.276pt 841.89pt; /* A4: Chromium's own \"A4\" rounds to 594.96 x 841.92 */\n  margin: 62pt 72pt 72pt;\n}\n:scope {\n  font: 10.95pt/13.5pt \"Libertinus Serif\", \"Linux Libertine O\", serif;\n  hyphens: auto;\n}\np,\nli {\n  word-spacing: -.08em; /* TeX shrinks interword glue; a browser only stretches */\n}\np {\n  margin: 0;\n  text-align: justify;\n}\n/* TeX indents every paragraph except the first one under a heading (and the abstract block) */\np {\n  text-indent: 11pt;\n}\nsection > p:nth-child(2), /* the first paragraph under a heading; not `h1 + p`: Paged.js rewrites `+` selectors into weaker ones */\nsection[role=\"doc-abstract\"] p,\n.p-keywords p {\n  text-indent: 0;\n}\nsup,\nsub {\n  line-height: 0;\n}\n.p-title {\n  font: 700 16.9pt/21.6pt \"Libertinus Sans\", Helvetica, Arial, sans-serif;\n  margin: 0 0 10.4pt;\n}\n.p-foot::footnote-call {\n  font-family: \"Libertinus Math\", \"Libertinus Serif\", serif; /* the star is a math symbol */\n  content: \"\\22C6\";\n  vertical-align: .5em;\n  font-size: 1em;\n  line-height: 0;\n}\n.p-authors {\n  text-align: left;\n  margin: 0 0 12pt;\n}\n.p-authors address {\n  font-style: normal;\n}\n.p-authors .author_name {\n  font-weight: 400;\n}\n.p-authors .given {\n  color: #808080;\n}\n.p-authors .affiliations {\n  display: block;\n  margin-top: 10pt;\n  font: italic 9pt/13pt \"Libertinus Serif\", serif;\n}\n.p-authors .affiliation {\n  display: block;\n}\nsection > h1 {\n  font: 700 13.7pt/14pt \"Libertinus Sans\", Helvetica, Arial, sans-serif;\n  margin: 3.5pt 0 11.5pt; /* the top margin is what TeX keeps at a page start (the ruler says 3.5, not the 6.5 the row table showed: the sans font's boxes differ); Paged.js keeps it there too, so the rest of the gap hangs below the previous block (it is cut at a page break) */\n}\nsection:has(+ section) {\n  margin-bottom: 19pt; /* collapses with the next heading's own 3.5pt, so this is the whole gap */\n}\nsection section > h1 {\n  font-size: 11pt;\n  line-height: 13pt;\n  margin: 4pt 0 8.5pt;\n}\nsection section:has(+ section) {\n  margin-bottom: 12pt;\n}\nsection > p:has(+ section) {\n  margin-bottom: 12pt;\n}\nsection > ul:has(+ section) {\n  margin-bottom: 12pt;\n}\nsection > ol:has(+ section) {\n  margin-bottom: 12pt;\n}\nsection > pre:has(+ section) {\n  margin-bottom: 12pt;\n}\nsection > section:nth-child(2) > h1 {\n  margin-top: 8pt; /* a subsection right under its section's heading */\n}\nsection section section > h1 {\n  font-size: 10.5pt;\n  line-height: 12pt;\n  font-style: italic;\n}\n:scope > section:not([role]) > h1::before {\n  content: counter(h1) \".\\2003\";\n}\n:scope > section:not([role]) > section:not([role]) > h1::before {\n  content: counter(h1) \".\" counter(h2) \".\\2003\";\n}\n:scope > section:not([role]) > section:not([role]) > section:not([role]) > h1::before {\n  content: counter(h1) \".\" counter(h2) \".\" counter(h3) \".\\2003\";\n}\nul,\nol {\n  margin: 12pt 0;\n  padding-left: 27pt;\n}\nul.tight,\nol.tight {\n  margin-top: 7.5pt; /* LaTeX adds \\partopsep (4.5pt) only when a blank line precedes the list */\n}\nli:not(:first-child) {\n  margin-top: 1.5pt;\n}\nli > p {\n  text-indent: 0;\n}\nli > pre {\n  margin-left: 0;\n}\npre {\n  margin: 11pt 0 6pt;\n  letter-spacing: .85pt; /* the class sets listings wider than the font's own advance */\n}\nsection[role=\"doc-abstract\"],\n.p-keywords {\n  margin-left: 45pt;\n}\nsection[role=\"doc-abstract\"] > h1,\n.p-keywords > h1 {\n  font: 700 11pt/12pt \"Libertinus Sans\", Helvetica, Arial, sans-serif;\n  margin: 17.5pt 0 -.5pt;\n}\n.p-keywords > h1 {\n  margin-top: 7pt;\n}\n.p-keywords {\n  padding-bottom: 23.5pt;\n}\nsection[role=\"doc-abstract\"] p,\n.p-keywords p {\n  font-size: 9pt;\n  line-height: 11pt;\n}\npre {\n  line-height: 13.5pt;\n}\nol > li::marker {\n  content: counter(list-item) \".\\2002\\2009\"; /* the number ends 9.5pt before the text, as ceurart's label box does */\n}\npre.lst {\n  margin-top: 5.5pt; /* lstlisting sits closer to the text above than verbatim does */\n}\ncode,\npre,\n.p-url {\n  font-family: \"Libertinus Mono\", \"Courier New\", monospace;\n  font-size: 9pt;\n}\n.p-foot {\n  float: footnote;\n  font: 400 9pt/11pt \"Libertinus Serif\", serif;\n}\n.p-note {\n  float: footnote;\n  font: 400 9pt/11pt \"Libertinus Serif\", serif;\n}\n.p-keywords::before {\n  content: none; /* the shared label is \"Keywords: \"; here \"Keywords\" is a heading */\n}\n/* the footnote is moved out of the paper box into the page's footnote area, so these are not scoped to it; its mark is a raised numeral, not the list marker */\n.pagedjs_footnote_content .p-foot[data-footnote-marker],\n.pagedjs_footnote_content .p-note[data-footnote-marker] {\n  list-style: none;\n}\n.pagedjs_footnote_content .p-foot[data-footnote-marker]::before {\n  content: \"*\";\n  vertical-align: super;\n  font-size: .7em;\n  line-height: 0;\n}\n.pagedjs_footnote_content .p-note[data-footnote-marker]::before {\n  content: attr(data-n);\n  vertical-align: super;\n  font-size: .7em;\n  line-height: 0;\n}\n.pagedjs_footnote_content .p-foot,\n.pagedjs_footnote_content .p-note {\n  font: 400 9pt/11pt \"Libertinus Serif\", serif;\n  text-align: left;\n  text-indent: 0;\n}\n.p-note.p-first {\n  counter-reset: footnote 1; /* the page-foot block's notes are Paged.js footnotes too, but the numbering starts at the first real note */\n}\n.p-note::footnote-call {\n  vertical-align: super;\n  font-size: .7em;\n  line-height: 0;\n}\n@page {\n  @footnote {\n    background: linear-gradient(#000, #000) top left / 40% .4pt no-repeat;\n    padding-top: 3pt;\n  }\n}\n/* the first page's foot block: footnotes with no call mark */\n/* one rule per selector: Paged.js rewrites only the first selector of a list that has ::footnote-call */\n.p-foot.p-conf::footnote-call {\n  content: none;\n}\n.p-foot.p-contact::footnote-call {\n  content: none;\n}\n.p-foot.p-copy::footnote-call {\n  content: none;\n}\n.pagedjs_footnote_content .p-foot.p-conf[data-footnote-marker]::before,\n.pagedjs_footnote_content .p-foot.p-contact[data-footnote-marker]::before,\n.pagedjs_footnote_content .p-foot.p-copy[data-footnote-marker]::before {\n  content: none;\n}\n.pagedjs_footnote_content .p-conf {\n  font-style: italic;\n}\n.pagedjs_footnote_content .p-copy {\n  font-size: 6pt;\n  line-height: 9pt;\n}\n.pagedjs_footnote_content img.cc {\n  height: 11pt;\n  vertical-align: middle;\n  margin-right: 3pt;\n}\n.pagedjs_footnote_content i.fa {\n  font: normal 900 9pt \"Font Awesome 5 Free\";\n}\n.pagedjs_footnote_content i.fa-r {\n  font-weight: 400;\n}\n.pagedjs_footnote_content .orcid {\n  display: inline-block;\n  width: 9pt;\n  height: 9pt;\n  border-radius: 50%;\n  background: #000;\n  color: #fff;\n  font: 700 5.5pt/9pt \"Libertinus Sans\", sans-serif;\n  text-align: center;\n}\n.pagedjs_footnote_content a {\n  color: #2f4f4f;\n  text-decoration: none;\n}\n.p-foot.p-mark::footnote-call {\n  content: none;\n}\n.pagedjs_footnote_content .p-foot.p-mark[data-footnote-marker]::before {\n  content: attr(data-mark);\n}\n/* the TeX logos, which are narrower than the letters set plainly */\n.latex sup {\n  font-size: .7em;\n  vertical-align: .2em;\n  margin: 0 -.3em 0 -.32em;\n}\n.latex sub {\n  font-size: 1em;\n  vertical-align: -.2em;\n  margin: 0 -.12em 0 -.1em;\n}\n",
  "rash/editor": "/* The RASH page on screen: the editor's original look (web page, theme colors). Screen only: the PDF keeps style.css. */\n.paper-pdf.ProseMirror { font: 16px/1.7 \"Helvetica Neue\", Helvetica, Arial, var(--font-inter), sans-serif; counter-reset: figure table listing; color: var(--ink); }\n.paper-pdf.ProseMirror .p-title { font: 700 30px/1.25 \"Helvetica Neue\", Helvetica, Arial, var(--font-inter), sans-serif; margin: 0 0 6px; letter-spacing: -.01em; text-align: left; }\n.paper-pdf.ProseMirror .p-subtitle { font: 400 20px/1.35 \"Helvetica Neue\", Helvetica, Arial, var(--font-inter), sans-serif; opacity: .8; margin: 0 0 10px; text-align: left; }\n.paper-pdf.ProseMirror .p-authors { font: 15px/1.5 var(--font-inter), system-ui, sans-serif; color: var(--muted); margin: 0 0 12px; text-align: left; }\n.paper-pdf.ProseMirror .p-keywords { font: 14px/1.5 var(--font-inter), system-ui, sans-serif; color: var(--muted); margin: 0 0 32px; }\n.paper-pdf.ProseMirror .p-keywords:not(.is-empty):not(:has(> .add-btn))::before { font-weight: 600; color: var(--ink); }\n.paper-pdf.ProseMirror section > h1 { font: 700 22px/1.3 \"Helvetica Neue\", Helvetica, Arial, var(--font-inter), sans-serif; margin: 32px 0 8px; }\n.paper-pdf.ProseMirror section section > h1 { font-size: 18px; }\n.paper-pdf.ProseMirror section section section > h1 { font-size: 16px; }\n.paper-pdf.ProseMirror > section:not([role]) > h1::before, .paper-pdf.ProseMirror > section:not([role]) section > h1::before { content: none; }\n.paper-pdf.ProseMirror section[role=\"doc-abstract\"] { background: var(--bg); border-radius: 6px; padding: 12px 20px 8px; margin: 0 0 16px; }\n.paper-pdf.ProseMirror section[role=\"doc-abstract\"] > h1 { margin: 0 0 4px; }\n.paper-pdf.ProseMirror section[role=\"doc-abstract\"] > h1, .paper-pdf.ProseMirror section[role=\"doc-acknowledgements\"] > h1, .paper-pdf.ProseMirror section[role=\"doc-bibliography\"] > h1 { font-size: 13px; text-transform: uppercase; letter-spacing: .08em; color: var(--muted); text-align: left; }\n.paper-pdf.ProseMirror section[role=\"doc-bibliography\"] { font-size: 15px; }\n.paper-pdf.ProseMirror p { margin: 0 0 12px; text-align: left; }\n.paper-pdf.ProseMirror ul { list-style: disc; padding-left: 24px; margin: 0 0 12px; }\n.paper-pdf.ProseMirror ol, .paper-pdf.ProseMirror section[role=\"doc-bibliography\"] > ul { list-style: decimal; padding-left: 24px; margin: 0 0 12px; }\n.paper-pdf.ProseMirror blockquote { border-left: 3px solid var(--line); margin: 16px 0; padding-left: 16px; color: var(--muted); font-style: italic; }\n.paper-pdf.ProseMirror pre { background: var(--bg); padding: 12px; border-radius: 6px; font: 13px/1.5 var(--font-jetbrains), ui-monospace, monospace; white-space: pre-wrap; }\n.paper-pdf.ProseMirror code { font: .85em var(--font-jetbrains), ui-monospace, monospace; background: var(--bg); padding: 1px 4px; border-radius: 3px; }\n.paper-pdf.ProseMirror pre code { background: none; padding: 0; }\n.paper-pdf.ProseMirror a:not(.orcid) { color: var(--accent); text-decoration: underline; }\n.paper-pdf.ProseMirror .emails a, .paper-pdf.ProseMirror a[href^=\"#fn-\"] { text-decoration: none; }\n.paper-pdf.ProseMirror { outline: none; }\n.paper-pdf.ProseMirror span[role=\"math\"] { font: .9em var(--font-jetbrains), ui-monospace, monospace; color: var(--accent); }\n.paper-pdf.ProseMirror span[role=\"math\"]::before, .paper-pdf.ProseMirror span[role=\"math\"]::after { content: \"$\"; opacity: .5; }\n.paper-pdf.ProseMirror p[role=\"math\"] { font: .9em var(--font-jetbrains), ui-monospace, monospace; color: var(--accent); text-align: center; margin: 16px 0; }\n.paper-pdf.ProseMirror figure { margin: 24px auto; text-align: center; width: fit-content; max-width: 100%; }\n.paper-pdf.ProseMirror figure img { max-width: 100%; border: 0; border-radius: 4px; display: block; margin-inline: auto; }\n.paper-pdf.ProseMirror figure p { margin: 0; }\n.paper-pdf.ProseMirror figcaption { font: 14px/1.5 var(--font-inter), system-ui, sans-serif; color: var(--muted); margin-top: 8px; }\n.paper-pdf.ProseMirror figcaption::before { font-weight: 600; color: var(--ink); }\n.paper-pdf.ProseMirror figure:has(> pre) { text-align: left; width: auto; }\n.paper-pdf.ProseMirror figure table { border: 0; font: 14px/1.5 var(--font-inter), system-ui, sans-serif; }\n.paper-pdf.ProseMirror figure th, .paper-pdf.ProseMirror figure td { border: 1px solid var(--line); padding: 4px 10px; min-width: 64px; text-align: left; }\n.paper-pdf.ProseMirror figure th { background: var(--bg); font-weight: 600; }\n/* \"+ Add ...\" chips sit in the flow, as they always did on this page (the global rule floats them into the margin). */\n.paper-pdf.ProseMirror .add-btn { position: static; margin: 0 0 0 -6px !important; white-space: normal; }\n.paper-pdf.ProseMirror .p-author ~ .byline-extra .add-btn, .paper-pdf.ProseMirror [data-rash-author] ~ .byline-extra .add-btn { margin-left: 0 !important; }\n.paper-pdf.ProseMirror .add-abstract { display: block; margin: -20px 0 8px -6px !important; }\n/* Empty title-block rows keep their height so their chip has a line of its own. */\n.paper-pdf.ProseMirror :is(.p-subtitle, .p-keywords, .p-authors) { height: auto !important; }\n.paper-pdf.ProseMirror .p-subtitle { margin: 0 0 10px !important; }\n.paper-pdf.ProseMirror .p-authors { margin: 0 0 12px !important; }\n.paper-pdf.ProseMirror .p-keywords { margin: 0 0 32px !important; }\n/* A row keeps its height whether it shows its chip or the cursor is in it, so clicking one doesn't move what is below. */\n.paper-pdf.ProseMirror .p-subtitle { min-height: 27px; }\n.paper-pdf.ProseMirror .p-authors { min-height: 23px; }\n.paper-pdf.ProseMirror .p-keywords { min-height: 22px; }\n/* ORCID badge: a green dot with a centered white \"iD\". */\n.paper-pdf.ProseMirror .orcid { display: inline-flex; align-items: center; justify-content: center; box-sizing: border-box; width: 14px; height: 14px; margin-left: 3px; padding: 0; border-radius: 50%; background: #a6ce39; color: #fff !important; font: 700 7px/1 var(--font-inter), system-ui, sans-serif; text-decoration: none !important; vertical-align: middle; }\n/* Commas between the names, as the PDF has them. */\n.paper-pdf.ProseMirror .p-authors > :is(span[data-rash-author], .author-marks):has(+ :is(span[data-rash-author], img.ProseMirror-separator))::after { content: \",\"; }\n",
  "rash/style": "@page { size: A4; margin: 20mm 22mm; @bottom-center { content: counter(page); font: 9pt Helvetica, Arial, sans-serif; } }\n/* The PDF is the page as the editor shows it (see editor.css): same type, left-aligned, grey abstract card, unnumbered headings. Light colors only. */\n.paper-pdf { --ink: #1d1b2c; --muted: #6b6880; --bg: #f6f5fa; --accent: #6d4fe3; --line: #e6e4ee; font: 16px/1.7 \"Helvetica Neue\", Helvetica, Arial, var(--font-inter), sans-serif; color: var(--ink); }\n.paper-pdf .p-title { font: 700 30px/1.25 \"Helvetica Neue\", Helvetica, Arial, var(--font-inter), sans-serif; letter-spacing: -.01em; text-align: left; margin: 0 0 6px; }\n.paper-pdf .p-subtitle { font: 400 20px/1.35 \"Helvetica Neue\", Helvetica, Arial, var(--font-inter), sans-serif; opacity: .8; text-align: left; margin: 0 0 10px; }\n.paper-pdf .p-authors { font: 15px/1.5 var(--font-inter), system-ui, sans-serif; color: var(--muted); text-align: left; margin: 0 0 12px; }\n.paper-pdf .p-author { color: var(--ink); }\n.paper-pdf .p-aff { font-size: 13px; line-height: 1.5; }\n.paper-pdf .p-aff:first-of-type { margin-top: 6px; }\n.paper-pdf .orcid { display: inline-flex; align-items: center; justify-content: center; width: 14px; height: 14px; margin-left: 3px; border-radius: 50%; background: #a6ce39; color: #fff; font: 700 7px/1 var(--font-inter), system-ui, sans-serif; vertical-align: 1px; }\n.paper-pdf .p-keywords { font: 14px/1.5 var(--font-inter), system-ui, sans-serif; color: var(--muted); margin: 0 0 32px; }\n.paper-pdf .p-keywords::before { color: var(--ink); font-weight: 600; }\n.paper-pdf p { margin: 0 0 12px; text-align: left; }\n.paper-pdf section > h1 { font: 700 22px/1.3 \"Helvetica Neue\", Helvetica, Arial, var(--font-inter), sans-serif; margin: 32px 0 8px; }\n.paper-pdf section section > h1 { font-size: 18px; } .paper-pdf section section section > h1 { font-size: 16px; }\n.paper-pdf > section:not([role]) > h1::before, .paper-pdf > section:not([role]) section > h1::before { content: none; }\n.paper-pdf section[role=\"doc-abstract\"] { background: var(--bg); border-radius: 6px; padding: 12px 20px 8px; margin: 0 0 16px; }\n.paper-pdf section[role=\"doc-abstract\"] > h1, .paper-pdf section[role=\"doc-acknowledgements\"] > h1, .paper-pdf section[role=\"doc-bibliography\"] > h1 { font-size: 13px; text-transform: uppercase; letter-spacing: .08em; color: var(--muted); text-align: left; margin: 0 0 4px; }\n.paper-pdf section[role=\"doc-bibliography\"] { font-size: 15px; }\n.paper-pdf ul { list-style: disc; padding-left: 24px; margin: 0 0 12px; }\n.paper-pdf ol, .paper-pdf section[role=\"doc-bibliography\"] > ul { list-style: decimal; padding-left: 24px; margin: 0 0 12px; }\n.paper-pdf section[role=\"doc-bibliography\"] li { padding-left: 0; text-indent: 0; }\n.paper-pdf section[role=\"doc-bibliography\"] li::before { content: none; }\n.paper-pdf blockquote { border-left: 3px solid var(--line); margin: 16px 0; padding-left: 16px; color: var(--muted); font-style: italic; }\n.paper-pdf pre { background: var(--bg); padding: 12px; border-radius: 6px; font: 13px/1.5 var(--font-jetbrains), ui-monospace, monospace; white-space: pre-wrap; }\n.paper-pdf code { font: .85em var(--font-jetbrains), ui-monospace, monospace; background: var(--bg); padding: 1px 4px; border-radius: 3px; }\n.paper-pdf pre code { background: none; padding: 0; }\n.paper-pdf a:not(.orcid) { color: var(--accent); text-decoration: underline; }\n.paper-pdf a[href^=\"#fn-\"] { text-decoration: none; }\n.paper-pdf span[role=\"math\"] { font: .9em var(--font-jetbrains), ui-monospace, monospace; font-style: normal; color: var(--accent); }\n.paper-pdf span[role=\"math\"]::before, .paper-pdf span[role=\"math\"]::after { content: \"$\"; opacity: .5; }\n.paper-pdf p[role=\"math\"] { font: .9em var(--font-jetbrains), ui-monospace, monospace; color: var(--accent); text-align: center; margin: 16px 0; }\n.paper-pdf figure { margin: 24px auto; width: fit-content; max-width: 100%; }\n.paper-pdf figure img { max-width: 100%; border: 0; border-radius: 4px; display: block; margin-inline: auto; }\n.paper-pdf figure p { margin: 0; }\n.paper-pdf figcaption { font: 14px/1.5 var(--font-inter), system-ui, sans-serif; color: var(--muted); margin-top: 8px; }\n.paper-pdf figcaption::before { font-weight: 600; color: var(--ink); }\n.paper-pdf figure:has(> pre) { text-align: left; width: auto; }\n.paper-pdf figure table { border: 0; font: 14px/1.5 var(--font-inter), system-ui, sans-serif; }\n.paper-pdf figure th, .paper-pdf figure td { border: 1px solid var(--line); padding: 4px 10px; min-width: 64px; text-align: left; }\n.paper-pdf figure th { background: var(--bg); font-weight: 600; border-bottom: 1px solid var(--line); }\n"
};
